const { Qified, MemoryMessageProvider } = await import('qified');
const topic = process.env.TOPIC;
const message = process.env.MESSAGE;
if (!topic) throw new Error('Missing required input: topic');
if (!message) throw new Error('Missing required input: message');
globalThis._qified = new Qified({ messageProviders: new MemoryMessageProvider() });
globalThis._topic = topic;
globalThis._message = message;

const q = globalThis._qified;
const topic = globalThis._topic;
const msg = globalThis._message;
const id = `msg-${Date.now()}`;
await q.publish(topic, { id, data: msg });
globalThis._status = 'published';
globalThis._msgId = id;
